/* fflate.min.js — Offiqa vendored ZIP helper (CSP-safe, no eval, no remote).
 *
 * NOTE: this is a self-contained, dependency-free ZIP reader/writer that mirrors
 * the slice of the fflate API the backup subsystem uses (zipSync / unzipSync /
 * strToU8 / strFromU8 / u8ToStr). It uses the STORE method (no compression), so
 * archives are valid .zip files openable by any tool. If the real fflate is later
 * vendored (with DEFLATE), this file can be swapped out — the API is compatible.
 *
 * Exposes window.fflate.
 */
(function (root) {
  "use strict";

  // ---- CRC-32 ----
  const CRC_TABLE = (() => {
    const t = new Uint32Array(256);
    for (let n = 0; n < 256; n++) {
      let c = n;
      for (let k = 0; k < 8; k++) c = (c & 1) ? (0xedb88320 ^ (c >>> 1)) : (c >>> 1);
      t[n] = c >>> 0;
    }
    return t;
  })();
  function crc32(u8) {
    let c = 0xffffffff;
    for (let i = 0; i < u8.length; i++) c = CRC_TABLE[(c ^ u8[i]) & 0xff] ^ (c >>> 8);
    return (c ^ 0xffffffff) >>> 0;
  }

  const _enc = new TextEncoder();
  const _dec = new TextDecoder();
  const strToU8   = (s) => _enc.encode(s);
  const strFromU8 = (u8) => _dec.decode(u8);

  // DOS time/date from now (good enough; archives are timestamped by filename).
  function dosDateTime(d) {
    const time = ((d.getHours() & 31) << 11) | ((d.getMinutes() & 63) << 5) | ((d.getSeconds() / 2) & 31);
    const date = (((d.getFullYear() - 1980) & 127) << 9) | (((d.getMonth() + 1) & 15) << 5) | (d.getDate() & 31);
    return { time: time & 0xffff, date: date & 0xffff };
  }

  // ---- writer ----
  // files: { "path/name": Uint8Array }  → Uint8Array (.zip bytes)
  function zipSync(files) {
    const names = Object.keys(files);
    const now = dosDateTime(new Date());
    const locals = [];
    const central = [];
    let offset = 0;

    for (const name of names) {
      const nameU8 = strToU8(name);
      let data = files[name];
      if (!(data instanceof Uint8Array)) data = new Uint8Array(data || 0);
      const crc = crc32(data);

      // Local file header (30 bytes + name) + data
      const lh = new Uint8Array(30 + nameU8.length);
      const lv = new DataView(lh.buffer);
      lv.setUint32(0, 0x04034b50, true);   // signature
      lv.setUint16(4, 20, true);           // version needed
      lv.setUint16(6, 0x0800, true);       // flags: bit 11 = UTF-8 names
      lv.setUint16(8, 0, true);            // method: 0 = store
      lv.setUint16(10, now.time, true);
      lv.setUint16(12, now.date, true);
      lv.setUint32(14, crc, true);
      lv.setUint32(18, data.length, true); // compressed size
      lv.setUint32(22, data.length, true); // uncompressed size
      lv.setUint16(26, nameU8.length, true);
      lv.setUint16(28, 0, true);           // extra length
      lh.set(nameU8, 30);

      locals.push(lh, data);

      // Central directory record
      const ch = new Uint8Array(46 + nameU8.length);
      const cv = new DataView(ch.buffer);
      cv.setUint32(0, 0x02014b50, true);   // signature
      cv.setUint16(4, 20, true);           // version made by
      cv.setUint16(6, 20, true);           // version needed
      cv.setUint16(8, 0x0800, true);       // flags
      cv.setUint16(10, 0, true);           // method
      cv.setUint16(12, now.time, true);
      cv.setUint16(14, now.date, true);
      cv.setUint32(16, crc, true);
      cv.setUint32(20, data.length, true);
      cv.setUint32(24, data.length, true);
      cv.setUint16(28, nameU8.length, true);
      cv.setUint16(30, 0, true);           // extra
      cv.setUint16(32, 0, true);           // comment
      cv.setUint16(34, 0, true);           // disk number
      cv.setUint16(36, 0, true);           // internal attrs
      cv.setUint32(38, 0, true);           // external attrs
      cv.setUint32(42, offset, true);      // local header offset
      ch.set(nameU8, 46);
      central.push(ch);

      offset += lh.length + data.length;
    }

    const centralSize = central.reduce((n, c) => n + c.length, 0);
    const centralOffset = offset;

    const eocd = new Uint8Array(22);
    const ev = new DataView(eocd.buffer);
    ev.setUint32(0, 0x06054b50, true);
    ev.setUint16(4, 0, true);
    ev.setUint16(6, 0, true);
    ev.setUint16(8, names.length, true);
    ev.setUint16(10, names.length, true);
    ev.setUint32(12, centralSize, true);
    ev.setUint32(16, centralOffset, true);
    ev.setUint16(20, 0, true);

    // concat everything
    const total = offset + centralSize + 22;
    const out = new Uint8Array(total);
    let p = 0;
    for (const chunk of locals)  { out.set(chunk, p); p += chunk.length; }
    for (const chunk of central) { out.set(chunk, p); p += chunk.length; }
    out.set(eocd, p);
    return out;
  }

  // ---- reader ----
  // data: Uint8Array  → { "path/name": Uint8Array }   (store entries only)
  function unzipSync(data) {
    const u8 = data instanceof Uint8Array ? data : new Uint8Array(data);
    const dv = new DataView(u8.buffer, u8.byteOffset, u8.byteLength);

    // find EOCD (scan backwards for signature)
    let eocd = -1;
    for (let i = u8.length - 22; i >= 0; i--) {
      if (dv.getUint32(i, true) === 0x06054b50) { eocd = i; break; }
    }
    if (eocd < 0) throw new Error("Not a zip file (no EOCD)");

    const count = dv.getUint16(eocd + 10, true);
    let p = dv.getUint32(eocd + 16, true); // central dir offset

    const out = {};
    for (let n = 0; n < count; n++) {
      if (dv.getUint32(p, true) !== 0x02014b50) break;
      const method = dv.getUint16(p + 10, true);
      const compSize = dv.getUint32(p + 20, true);
      const nameLen = dv.getUint16(p + 28, true);
      const extraLen = dv.getUint16(p + 30, true);
      const commentLen = dv.getUint16(p + 32, true);
      const localOff = dv.getUint32(p + 42, true);
      const name = strFromU8(u8.subarray(p + 46, p + 46 + nameLen));

      // jump to local header to read its name/extra lengths, then data
      const lNameLen = dv.getUint16(localOff + 26, true);
      const lExtraLen = dv.getUint16(localOff + 28, true);
      const dataStart = localOff + 30 + lNameLen + lExtraLen;
      if (method !== 0) throw new Error("Unsupported compression in " + name + " (only store)");
      out[name] = u8.subarray(dataStart, dataStart + compSize);

      p += 46 + nameLen + extraLen + commentLen;
    }
    return out;
  }

  root.fflate = { zipSync, unzipSync, strToU8, strFromU8, crc32 };
})(typeof self !== "undefined" ? self : this);
